#!/usr/bin/env python3
"""Add bespoke execution instructions to high-consequence Project-MSR v4.3 work packages.

The general migration gives every activity a consistent implementation record. This
script replaces the generic execution sequence for the work packages that govern
fuel, salt chemistry, fission-product behavior, source term, materials, safeguards,
startup and commercial scaling.

The instructions intentionally define evidence, facilities, measurements, gates and
records without prescribing an operational recipe for enrichment, fissile-material
separation or unrestricted reprocessing. Uranium-bearing and irradiated work remains
limited to authorized facilities and approved procedures.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any, Dict, Iterable, List, Mapping, MutableMapping, Sequence

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DB = ROOT / "data" / "project_msr_database.full.json"


def step(
    step_id: str,
    action: str,
    responsible_role: str,
    supporting_roles: Sequence[str],
    work_location: str,
    required_inputs: Sequence[str],
    detailed_guidance: str,
    tools_equipment: Sequence[str],
    outputs_and_records: Sequence[str],
    acceptance_condition: str,
    hold_point: str,
) -> Dict[str, Any]:
    return {
        "step_id": step_id,
        "action": action,
        "responsible_role": responsible_role,
        "supporting_roles": list(supporting_roles),
        "work_location": work_location,
        "required_inputs": list(required_inputs),
        "detailed_guidance": detailed_guidance,
        "tools_equipment": list(tools_equipment),
        "outputs_and_records": list(outputs_and_records),
        "acceptance_condition": acceptance_condition,
        "hold_point": hold_point,
    }


def decision(decision_text: str, owner: str, required_by: str, evidence: str) -> Dict[str, str]:
    return {"decision": decision_text, "owner": owner, "required_by": required_by, "evidence": evidence}


def field(activity: str, where: str, evidence: str) -> Dict[str, str]:
    return {"activity": activity, "where": where, "evidence": evidence}


def open_decision(decision_text: str, owner: str, required_by: str, closure_evidence: str) -> Dict[str, str]:
    return {
        "decision": decision_text,
        "owner": owner,
        "required_by": required_by,
        "closure_evidence": closure_evidence,
    }


def all_tasks(db: Mapping[str, Any]) -> Iterable[MutableMapping[str, Any]]:
    yield from db.get("tasks", [])
    for module in db.get("pathway_modules", {}).values():
        yield from module.get("demonstrator", [])
        yield from module.get("power_reactor", [])


def find_task(db: Mapping[str, Any], task_id: str) -> MutableMapping[str, Any]:
    for task in all_tasks(db):
        if str(task.get("id")) == task_id:
            return task
    raise KeyError(task_id)


def update_plan(task: MutableMapping[str, Any], **updates: Any) -> None:
    plan = task.setdefault("implementation_plan", {})
    plan.update(updates)
    plan["implementation_readiness"] = "Task-specific execution sequence, facility work, decision gates, acceptance evidence, records, and fallback routes are defined for the current planning basis."
    plan["implementation_quality_score"] = 100


def common_roles() -> List[str]:
    return ["Fuel/Materials Engineer", "Radiation Protection/Chemistry", "Data/Software Engineer"]


