def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--database", type=Path, default=DEFAULT_DB)
    args = parser.parse_args()
    db = json.loads(args.database.read_text(encoding="utf-8"))
    apply(db)
    args.database.write_text(json.dumps(db, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"Updated high-consequence implementation plans in {args.database}")


if __name__ == "__main__":
    main()
